#include <iostream>
#include <vector>
#include <cstring>
#include <algorithm>

using namespace std;

typedef long long ll;

ll n, k, memo[100005];
vector<ll> arr;

ll solve() {
    memo[0] = 0; // Base case
    for (ll i = 1; i < n; ++i) {
        memo[i] = 1e9; // Initialize with a large number
        ll current_value = arr[i]; // Store current value to avoid repeated access
        for (int j = 1; j <= k && j <= i; j++) {
            // Calculate the difference once and reuse it
            ll diff = abs(current_value - arr[i - j]);
            memo[i] = min(memo[i], memo[i - j] + diff);
        }
    }
    return memo[n - 1];
}

int main() {
    cin >> n >> k;
    arr.resize(n);
    for (int i = 0; i < n; i++)
        cin >> arr[i];

    cout << solve();
    return 0;
}

